def calc(expr):
    parts = expr.split()
    if len(parts) != 3:
        return "오류: 형식이 잘못됐어요"
    try:
        a = float(parts[0])
        b = float(parts[2])
    except ValueError:
        return "오류: 숫자가 아니에요"
    op = parts[1]
    try:
        if op == "+":
            value = a + b
        elif op == "-":
            value = a - b
        elif op == "*":
            value = a * b
        elif op == "/":
            value = a / b
        else:
            return "오류: 지원하지 않는 연산"
    except ZeroDivisionError:
        return "오류: 0으로 나눌 수 없어요"
    return f"결과: {value:g}"

